<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; class seo extends lib { var $log_id = 'seo'; public function __construct() { add_filter( 'qqworld-collector-settings-nav-tabs', array($this, 'add_nav_tab') ); add_action( 'qqworld-collector-settings-nav-sections', array($this, 'add_nav_section') ); add_action( 'init', array($this, 'initialize') ); add_action( 'qqworld-collector-seo-remove-actions', array($this, 'remove_actions') ); add_action( 'qqworld-collector-submit-link-to-baidu', array($this, 'submit_post'), 10, 2 ); add_action( 'qqworld-collector-submit-urls-to-baidu', array($this, 'submit_urls'), 10, 3 ); add_action( 'wp_ajax_qqworld-collector-seo-baidu-check-inclusion', array($this, 'baidu_check_inclusion') ); add_action( 'wp_ajax_nopriv_qqworld-collector-seo-baidu-check-inclusion', array($this, 'baidu_check_inclusion') ); add_action( 'qqworld-collector-submit-link-to-shenma', array($this, 'submit_shenma_post'), 10, 2 ); add_action( 'qqworld-collector-submit-urls-to-shenma', array($this, 'submit_shenma_urls'), 10, 3 ); add_action( 'qqworld-collector-submit-link-to-bing', array($this, 'submit_bing_post'), 10, 2 ); add_action( 'qqworld-collector-submit-urls-to-bing', array($this, 'submit_bing_urls'), 10, 3 ); add_action( 'add_meta_boxes', array($this, 'add_meta_boxes') ); } public function init() {} public function add_nav_tab($nav_tabs) { $nav_tabs['seo'] = __('Search Engine', $this->text_domain); return $nav_tabs; } public function add_nav_section() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'settings-seo.php'; } public function initialize() { if ($this->options->qc_baidu_link_submit_enabled == 1 && !empty($this->options->qc_baidu_link_submit_post_types)) { foreach ($this->options->qc_baidu_link_submit_post_types as $post_type) { add_action( "save_post_{$post_type}", array($this, 'submit_link_to_baidu'), 10, 3 ); } } if ($this->options->qc_shenma_link_submit_enabled == 1 && !empty($this->options->qc_shenma_link_submit_post_types)) { foreach ($this->options->qc_shenma_link_submit_post_types as $post_type) { add_action( "save_post_{$post_type}", array($this, 'submit_link_to_shenma'), 10, 3 ); } } if ($this->options->qc_bing_link_submit_enabled == 1 && !empty($this->options->qc_bing_link_submit_post_types)) { foreach ($this->options->qc_bing_link_submit_post_types as $post_type) { add_action( "save_post_{$post_type}", array($this, 'submit_link_to_bing'), 10, 3 ); } } } public function remove_actions() { if ($this->options->qc_baidu_link_submit_enabled == 1 && !empty($this->options->qc_baidu_link_submit_post_types)) { foreach ($this->options->qc_baidu_link_submit_post_types as $post_type) { if (has_action( "save_post_{$post_type}", array($this, 'submit_link_to_baidu') )) remove_action( "save_post_{$post_type}", array($this, 'submit_link_to_baidu') ); } } if ($this->options->qc_shenma_link_submit_enabled == 1 && !empty($this->options->qc_shenma_link_submit_post_types)) { foreach ($this->options->qc_shenma_link_submit_post_types as $post_type) { if (has_action( "save_post_{$post_type}", array($this, 'submit_link_to_shenma') )) remove_action( "save_post_{$post_type}", array($this, 'submit_link_to_shenma') ); } } if ($this->options->qc_bing_link_submit_enabled == 1 && !empty($this->options->qc_bing_link_submit_post_types)) { foreach ($this->options->qc_bing_link_submit_post_types as $post_type) { if (has_action( "save_post_{$post_type}", array($this, 'submit_link_to_bing') )) remove_action( "save_post_{$post_type}", array($this, 'submit_link_to_bing') ); } } } public function submit($urls, $post_ID, $type = 'normal') { $post_type = get_post_type($post_ID); if ($type == 'normal') { if ( empty($this->options->qc_baidu_link_submit_post_types) || !in_array($post_type, $this->options->qc_baidu_link_submit_post_types) ) return false; } else { if ( empty($this->options->qc_baidu_link_submit_post_types_for_quick_inclusion) || !in_array($post_type, $this->options->qc_baidu_link_submit_post_types_for_quick_inclusion) ) return false; } if ($type == 'daily' && get_post_meta($post_ID, 'baidu-daily', true)) return true; $urls = apply_filters( 'qqworld-collector-submit-urls', $urls ); do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to Baidu $urls ('.$type.'):', print_r($urls, true) ); $host = parse_url($urls[0]); $api = 'http://data.zz.baidu.com/urls?site='.$host['scheme'].'://'.$host['host'].'&token='.$this->options->qc_baidu_link_submit_token; if ($type != 'normal') $api .= '&type='.$type; $ch = curl_init(); $options = array( CURLOPT_URL => $api, CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_CONNECTTIMEOUT => 5, CURLOPT_TIMEOUT => 30, CURLOPT_POSTFIELDS => implode("\n", $urls), CURLOPT_HTTPHEADER => array('Content-Type: text/plain'), ); curl_setopt_array($ch, $options); $result = curl_exec($ch); $result = json_decode($result, true); if ($result && isset($result['error'])) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to Baidu failed ('.$type.'), ERROR:', print_r($result['message'], true) ); return false; } else { if ($type == 'daily') update_post_meta($post_ID, 'baidu-daily', 1); } return true; } public function submit_link_to_baidu($post_ID, $post, $update) { if ($post->post_status != 'publish') return; if ( defined('BAIDU_SUBMITED_' . $post_ID) ) return true; define( 'BAIDU_SUBMITED_' . $post_ID, 1 ); if ($this->options->qc_baidu_link_submit_cron && !wp_next_scheduled('qqworld-collector-submit-link-to-baidu', array($post_ID, $post))) { wp_schedule_single_event( time() + 5, 'qqworld-collector-submit-link-to-baidu', array($post_ID, $post) ); } $urls = array(get_permalink($post_ID)); $this->submit($urls, $post_ID); if ($this->options->qc_baidu_link_submit_daily) $this->submit($urls, $post_ID, 'daily'); } public function submit_urls($urls, $post_type, $post_id) { if ( defined('BAIDU_SUBMITED_' . $post_id) ) return true; define( 'BAIDU_SUBMITED_' . $post_id, 1 ); if ($this->options->qc_baidu_link_submit_enabled == 1) { $this->submit($urls, $post_id); if ($this->options->qc_baidu_link_submit_daily) $this->submit($urls, $post_id, 'daily'); } } public function submit_post($post_ID, $post) { if ( defined('BAIDU_SUBMITED_' . $post_ID) ) return true; define( 'BAIDU_SUBMITED_' . $post_ID, 1 ); $urls = array(get_permalink($post_ID)); $this->submit($urls); if ($this->options->qc_baidu_link_submit_daily) $this->submit($urls, $post_ID, 'daily'); } public function baidu_check_inclusion() { if (!isset($_POST['url'])) exit; if ($this->baidu_included($_POST['url'])) { $results = array( 'success' => 1, 'msg' => _x('Included', 'seo', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => _x('Not included', 'seo', $this->text_domain) ); } print json_encode($results); exit; } public function submit_shenma($urls) { $urls = apply_filters( 'qqworld-collector-submit-urls', $urls ); do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to Shenma $urls:', print_r($urls, true) ); $host = parse_url($urls[0]); $resource_name = apply_filters('qqworld-collector-seo-shenma-resource-name', 'mip_add'); $api = 'https://data.zhanzhang.sm.cn/push?site='.$host['host'].'&user_name='.$this->options->qc_shenma_link_submit_username.'&resource_name='.$resource_name.'&token='.$this->options->qc_shenma_link_submit_authkey; $ch = curl_init(); $options = array( CURLOPT_URL => $api, CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_CONNECTTIMEOUT => 5, CURLOPT_TIMEOUT => 30, CURLOPT_POSTFIELDS => implode("\n", $urls), CURLOPT_HTTPHEADER => array('Content-Type: text/plain'), ); curl_setopt_array($ch, $options); $result = curl_exec($ch); $result = json_decode($result, true); if (!$result || isset($result['returnCode']) && $result['returnCode'] != 200) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to Shenma failed, ERROR:', print_r($result['errorMsg'], true) ); return false; } return true; } public function submit_link_to_shenma($post_ID, $post, $update) { if ($post->post_status != 'publish') return; if ( defined('SHENMA_SUBMITED_' . $post_ID) ) return true; define( 'SHENMA_SUBMITED_' . $post_ID, 1 ); if ($this->options->qc_shenma_link_submit_cron && !wp_next_scheduled('qqworld-collector-submit-link-to-shenma', array($post_ID, $post))) { wp_schedule_single_event( time() + 5, 'qqworld-collector-submit-link-to-shenma', array($post_ID, $post) ); } $urls = array(get_permalink($post_ID)); $this->submit_shenma($urls); } public function submit_shenma_urls($urls, $post_type, $post_id) { if ( defined('SHENMA_SUBMITED_' . $post_id) ) return; define( 'SHENMA_SUBMITED_' . $post_id, 1 ); if ($this->options->qc_shenma_link_submit_enabled == 1 && !empty($this->options->qc_shenma_link_submit_post_types) && in_array($post_type, $this->options->qc_shenma_link_submit_post_types)) { $this->submit_shenma($urls); } } public function submit_shenma_post($post_ID, $post) { if ( defined('SHENMA_SUBMITED_' . $post_ID) ) return; define( 'SHENMA_SUBMITED_' . $post_ID, 1 ); $urls = array(get_permalink($post_ID)); $this->submit_shenma($urls); } public function submit_bing($urls) { global $wp_version; $urls = apply_filters( 'qqworld-collector-submit-urls', $urls ); do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing $urls:', print_r($urls, true) ); $type = 'add'; $siteUrl = home_url(); if ($this->options->qc_bing_link_submit_apikey) { $api = "https://www.bing.com/webmaster/api.svc/json/WPSubmitUrl?apikey=" . $this->options->qc_bing_link_submit_apikey . "&auto=1&type=" . $type . "&client=wp_v_".$wp_version."&siteUrl=" . $siteUrl; $data = array( 'siteUrl' => $siteUrl, 'url' => $urls[0] ); $args = array( 'sslverify' => false, 'body' => json_encode($data, JSON_INVALID_UTF8_IGNORE), 'headers' => array( 'Content-Type' => 'application/json') ); $response = wp_remote_post($api, $args); if (is_wp_error( $response )) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing failed, WP_Error:', print_r($response->get_error_messages(), true) ); } else { if (isset($response['errors'])) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing failed, Error:', 'RequestFailed' ); } try { if ($response['response']['code'] === 200) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing failed, Success:', $urls[0] ); return true; } else { if ($response['response']['code'] >= 500) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing failed, Error:', $response['response']['message'] ); } else { $message = json_decode($response['body'])->{'Message'}; do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing failed, Error:', $message ); } } } catch (\Throwable $th) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing failed, Error:', 'RequestFailed' ); } } } if ($this->options->qc_bing_link_submit_indexnow_apikey) { $api = 'https://www.bing.com/indexnow?url=' . $urls[0] . '&key=' . $this->options->qc_bing_link_submit_indexnow_apikey; $response = wp_remote_get($api); if (is_wp_error( $response )) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing indexnow failed, WP_Error:', print_r($response->get_error_messages(), true) ); } else { $response_code = wp_remote_retrieve_response_code($response); switch ($response_code) { case 400: do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing indexnow failed, WP_Error:', '400 Bad request, Invalid format' ); break; case 403: do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing indexnow failed, WP_Error:', '403 Forbidden, In case of key not valid (e.g. key not found, file found but key not in the file)' ); break; case 422: do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing indexnow failed, WP_Error:', '422 Unprocessable Entity, In case of URLs don’t belong to the host or the key is not matching the schema in the protocol' ); break; case 429: do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to bing indexnow failed, WP_Error:', '429 Too Many Requests, Too Many Requests (potential Spam)' ); break; } } } return false; } public function submit_link_to_bing($post_ID, $post, $update) { if ($post->post_status != 'publish') return; if ( defined('BING_SUBMITED_' . $post_ID) ) return true; define( 'BING_SUBMITED_' . $post_ID, 1 ); if ($this->options->qc_bing_link_submit_cron && !wp_next_scheduled('qqworld-collector-submit-link-to-bing', array($post_ID, $post))) { wp_schedule_single_event( time() + 5, 'qqworld-collector-submit-link-to-bing', array($post_ID, $post) ); } $urls = array(get_permalink($post_ID)); $this->submit_bing($urls); } public function submit_bing_urls($urls, $post_type, $post_id) { if ( defined('BING_SUBMITED_' . $post_id) ) return; define( 'BING_SUBMITED_' . $post_id, 1 ); if ($this->options->qc_bing_link_submit_enabled == 1 && !empty($this->options->qc_bing_link_submit_post_types) && in_array($post_type, $this->options->qc_bing_link_submit_post_types)) { $this->submit_bing($urls); } } public function submit_bing_post($post_ID, $post) { if ( defined('BING_SUBMITED_' . $post_ID) ) return; define( 'BING_SUBMITED_' . $post_ID, 1 ); $urls = array(get_permalink($post_ID)); $this->submit_bing($urls); } public function add_meta_boxes() { $id = 'suggestion_keywords'; $title = __( 'Suggestion Keywords', $this->text_domain ); $callback = array($this, 'suggestion_keywords'); $screen = get_post_types(array('public'=>true, 'show_ui' => true)); $context = 'side'; $priority = 'default'; $callback_args = null; add_meta_box($id, $title, $callback, $screen, $context, $priority, $callback_args ); } public function suggestion_keywords($post) { ?><div class="tagsdiv">
	<p><select class="selectstyle" id="suggestion_keywords_se_types" style="width: 100%;">
		<option value="baidu"><?php _e('Baidu', $this->text_domain); ?></option>
		<!--<option value="sogou"><?php _e('SoGou', $this->text_domain); ?></option>-->
		<option value="360"><?php _e('360', $this->text_domain); ?></option>
