		<input id="suggestion_keywords_submit" type="button" class="button tagadd" value="<?php _e('Suggest', $this->text_domain); ?>" />
	</p>
	<p class="howto"><?php _e('Separate keywords with commas', $this->text_domain); ?></p>
	<p id="suggestion_keywords_results"></p>
